 WHEN 'p10.delta-per-fold-decay-30m.v1' THEN 'WFO'
 WHEN 'p10.delta-three-window-optimized-30m.v1' THEN 'OPT'
 WHEN 'p10.delta-wfo-temporal-1h.v1' THEN 'WFO'
 WHEN 'p10.delta-causal-inner-1h.v1' THEN 'WFO'
 WHEN 'p10.delta-per-fold-decay-1h.v1' THEN 'WFO'
 WHEN 'p10.delta-three-window-optimized-1h.v1' THEN 'OPT'
 WHEN 'p10.delta-wfo-temporal-4h.v1' THEN 'WFO'
