 WHEN 'p10.delta-per-fold-decay-1d.v1' THEN 'WFO'
 WHEN 'p10.delta-three-window-optimized-1d.v1' THEN 'OPT'
 WHEN 'p10.delta-mode3-global-1h.v1' THEN 'WFO'
 WHEN 'p10.delta-mode3-global-1m.v1' THEN 'WFO'
 WHEN 'p10.delta-mode3-global-5m.v1' THEN 'WFO'
 WHEN 'p10.delta-mode3-global-15m.v1' THEN 'WFO'
